"""Checksum-verified ephemeral execution for trusted remote skill helpers."""

from __future__ import annotations

import hashlib
import json
import os
import re
import subprocess
import sys
import tempfile
from pathlib import Path
from typing import Any

import requests

from gxl_paperclip import __version__

from .skill import skill_request_headers

_RUNTIME_SCHEMA = "paperclip.skill-runtime.v1"
_SAFE_NAME = re.compile(r"^[a-z0-9][a-z0-9-]*$")
_MAX_MANIFEST_BYTES = 256 * 1024
_MAX_SCRIPT_BYTES = 5 * 1024 * 1024
_MAX_WHEEL_BYTES = 50 * 1024 * 1024
_DEFAULT_TIMEOUT = 300


class SkillRuntimeError(RuntimeError):
    """A remote helper could not be safely prepared or executed."""


def _download(
    base_url: str,
    endpoint: str,
    *,
    limit: int,
    authenticated: bool,
) -> tuple[bytes, requests.Response]:
    if not endpoint.startswith("/") or ".." in endpoint.split("/"):
        raise SkillRuntimeError("runtime manifest contains an unsafe endpoint")
    headers = skill_request_headers() if authenticated else {}
    try:
        response = requests.get(
            f"{base_url.rstrip('/')}{endpoint}",
            headers=headers,
            timeout=20,
            stream=True,
        )
        response.raise_for_status()
    except requests.RequestException as exc:
        raise SkillRuntimeError(f"failed to download {endpoint}: {exc}") from exc
    length = response.headers.get("Content-Length")
    if length and int(length) > limit:
        raise SkillRuntimeError(f"{endpoint} exceeds its download limit")
    chunks: list[bytes] = []
    total = 0
    for chunk in response.iter_content(chunk_size=64 * 1024):
        if not chunk:
            continue
        total += len(chunk)
        if total > limit:
            raise SkillRuntimeError(f"{endpoint} exceeds its download limit")
        chunks.append(chunk)
    return b"".join(chunks), response


def _version_tuple(value: str) -> tuple[int, ...]:
    match = re.match(r"^(\d+(?:\.\d+)*)", value)
    if not match:
        return ()
    return tuple(int(part) for part in match.group(1).split("."))


def _validate_checksum(body: bytes, expected: Any, label: str) -> None:
    if (
        not isinstance(expected, str)
        or len(expected) != 64
        or any(char not in "0123456789abcdef" for char in expected)
    ):
        raise SkillRuntimeError(f"{label} has an invalid checksum")
    if hashlib.sha256(body).hexdigest() != expected:
        raise SkillRuntimeError(f"{label} checksum mismatch")


def _load_manifest(skills_url: str, skill: str) -> dict[str, Any]:
    if not _SAFE_NAME.fullmatch(skill):
        raise SkillRuntimeError("invalid routine name")
    body, _ = _download(
        skills_url,
        f"/skills/skills/{skill}/runtime.json",
        limit=_MAX_MANIFEST_BYTES,
        authenticated=True,
    )
    try:
        manifest = json.loads(body)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise SkillRuntimeError("invalid routine runtime manifest") from exc
    if not isinstance(manifest, dict) or manifest.get("schema_version") != _RUNTIME_SCHEMA:
        raise SkillRuntimeError("unsupported routine runtime manifest")
    minimum = manifest.get("minimum_cli_version")
    if not isinstance(minimum, str) or _version_tuple(__version__) < _version_tuple(minimum):
        raise SkillRuntimeError(
            f"this helper requires Paperclip {minimum or 'a newer version'}; "
            "run `paperclip update`"
        )
    return manifest


def _operation_descriptor(
    manifest: dict[str, Any],
    operation: str,
) -> dict[str, Any]:
    if not _SAFE_NAME.fullmatch(operation) or operation in {"run", "preview"}:
        raise SkillRuntimeError("invalid or prohibited helper operation")
    operations = manifest.get("operations")
    descriptor = operations.get(operation) if isinstance(operations, dict) else None
    if not isinstance(descriptor, dict):
        raise SkillRuntimeError(f'helper operation "{operation}" is not available')
    return descriptor


def _entry(body: bytes, descriptor: dict[str, Any], label: str) -> str:
    endpoint = descriptor.get("entry")
    if (
        not isinstance(endpoint, str)
        or not endpoint.startswith("scripts/")
        or "/" in endpoint.removeprefix("scripts/")
        or not endpoint.endswith(".py")
    ):
        raise SkillRuntimeError(f"{label} has an unsafe entrypoint")
    expected_size = descriptor.get("size")
    if (
        not isinstance(expected_size, int)
        or isinstance(expected_size, bool)
        or expected_size < 0
        or len(body) != expected_size
    ):
        raise SkillRuntimeError(f"{label} size mismatch")
    _validate_checksum(body, descriptor.get("sha256"), label)
    return endpoint


def _target_directory(
    raw_directory: str,
    *,
    may_create: bool,
) -> Path:
    raw = Path(raw_directory).expanduser()
    if raw.exists() and raw.is_symlink():
        raise SkillRuntimeError("helper directory cannot be a symlink")
    if not raw.exists() and not may_create:
        raise SkillRuntimeError(f"helper directory does not exist: {raw}")
    parent = raw.parent.resolve()
    if not parent.is_dir():
        raise SkillRuntimeError(f"helper directory parent does not exist: {parent}")
    return raw.resolve()


def _helper_arguments(
    descriptor: dict[str, Any],
    directory: Path,
    arguments: tuple[str, ...],
    *,
    json_output: bool,
) -> list[str]:
    if len(arguments) > 100 or any("\x00" in value or len(value) > 4096 for value in arguments):
        raise SkillRuntimeError("helper arguments exceed safe limits")
    prepend = descriptor.get("prepend", [])
    if not isinstance(prepend, list) or any(not isinstance(value, str) for value in prepend):
        raise SkillRuntimeError("runtime manifest has invalid fixed arguments")
    command = list(prepend)
    directory_spec = descriptor.get("directory")
    if not isinstance(directory_spec, dict):
        raise SkillRuntimeError("runtime manifest is missing directory handling")
    kind = directory_spec.get("kind")
    value = directory_spec.get("value")
    if kind == "flag" and isinstance(value, str) and value.startswith("--"):
        command.extend([value, str(directory)])
        command.extend(arguments)
    elif kind == "positional" and value == 0:
        command.append(str(directory))
        command.extend(arguments)
    else:
        raise SkillRuntimeError("runtime manifest has invalid directory handling")
    if json_output and "--json" not in command:
        command.append("--json")
    return command


def _runtime_environment(
    temp_dir: Path,
    wheel: Path,
    routine_name: str,
) -> dict[str, str]:
    keep_exact = {
        "HOME",
        "PATH",
        "LANG",
        "LC_ALL",
        "SSL_CERT_FILE",
        "REQUESTS_CA_BUNDLE",
    }
    environment = {
        key: value
        for key, value in os.environ.items()
        if key in keep_exact or key.startswith("PAPERCLIP_")
    }
    existing = os.environ.get("PYTHONPATH", "")
    paths = [str(temp_dir), str(wheel)]
    if existing:
        paths.append(existing)
    environment["PYTHONPATH"] = os.pathsep.join(paths)
    environment["PYTHONDONTWRITEBYTECODE"] = "1"
    environment["PAPERCLIP_ROUTINE_NAME"] = routine_name
    return environment


def run_remote_helper(
    *,
    skills_url: str,
    bundle_url: str,
    skill: str,
    operation: str,
    directory: str,
    arguments: tuple[str, ...],
    json_output: bool,
    timeout: int = _DEFAULT_TIMEOUT,
) -> subprocess.CompletedProcess[str]:
    """Download, verify, execute, and delete one trusted helper bundle."""
    manifest = _load_manifest(skills_url, skill)
    descriptor = _operation_descriptor(manifest, operation)
    directory_spec = descriptor.get("directory", {})
    target = _target_directory(
        directory,
        may_create=bool(directory_spec.get("may_create")),
    )
    helper_args = _helper_arguments(
        descriptor,
        target,
        arguments,
        json_output=json_output,
    )

    bundle = manifest.get("bundle")
    if not isinstance(bundle, dict):
        raise SkillRuntimeError("runtime manifest is missing its bundle")
    wheel_endpoint = bundle.get("url")
    metadata_endpoint = bundle.get("metadata_url")
    checksum_field = bundle.get("sha256_field")
    if (
        wheel_endpoint != "/paperclip.whl"
        or metadata_endpoint != "/version.json"
        or checksum_field != "sha256"
    ):
        raise SkillRuntimeError("runtime manifest has an unsupported bundle")

    metadata_body, _ = _download(
        bundle_url,
        metadata_endpoint,
        limit=_MAX_MANIFEST_BYTES,
        authenticated=False,
    )
    try:
        metadata = json.loads(metadata_body)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise SkillRuntimeError("invalid Paperclip bundle metadata") from exc
    expected_wheel_sha = metadata.get(checksum_field)
    wheel_body, _ = _download(
        bundle_url,
        wheel_endpoint,
        limit=_MAX_WHEEL_BYTES,
        authenticated=False,
    )
    _validate_checksum(wheel_body, expected_wheel_sha, "Paperclip helper bundle")

    entry_body, _ = _download(
        skills_url,
        f"/skills/{descriptor['entry']}",
        limit=_MAX_SCRIPT_BYTES,
        authenticated=True,
    )
    entry_endpoint = _entry(entry_body, descriptor, operation)

    with tempfile.TemporaryDirectory(prefix="paperclip-skill-") as raw_temp:
        temp_dir = Path(raw_temp)
        entry_path = temp_dir / Path(entry_endpoint).name
        entry_path.write_bytes(entry_body)
        for dependency in descriptor.get("dependencies", []):
            dependency_body, _ = _download(
                skills_url,
                f"/skills/{dependency['entry']}",
                limit=_MAX_SCRIPT_BYTES,
                authenticated=True,
            )
            dependency_endpoint = _entry(
                dependency_body,
                dependency,
                f"{operation} dependency",
            )
            (temp_dir / Path(dependency_endpoint).name).write_bytes(dependency_body)
        wheel_path = temp_dir / "paperclip.whl"
        wheel_path.write_bytes(wheel_body)
        try:
            return subprocess.run(
                [sys.executable, str(entry_path), *helper_args],
                cwd=str(target if target.is_dir() else target.parent),
                env=_runtime_environment(temp_dir, wheel_path, skill),
                text=True,
                capture_output=True,
                timeout=timeout,
                check=False,
            )
        except subprocess.TimeoutExpired as exc:
            raise SkillRuntimeError(
                f'helper operation "{operation}" timed out after {timeout}s'
            ) from exc
